def main():
    assert set(P.keys()) == set(IDS), "id 集與本批不一致"
    os.makedirs(BASE, exist_ok=True)
    n = 0
    for cid in IDS:
        rec = {"case_id": cid}
        rec.update(P[cid])
        with open(os.path.join(BASE, cid + ".json"), "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        n += 1
    assert n == 20, "寫出文件數 != 20"
    cm = sum(1 for c in IDS if P[c]["trigger"]["changed_main"])
    ru = sum(1 for c in IDS if P[c]["trigger"]["reserve_used"])
    di = sum(1 for c in IDS if P[c]["trigger"]["disputed"])
    print("written:", n)
    print("trigger changed_main:", cm, "reserve_used:", ru, "disputed:", di)

if __name__ == "__main__":
    main()
